"""Build the final Russian report from measured CSV/JSON artifacts."""
import csv,json
from pathlib import Path
from docx import Document
from docx.shared import Cm,Pt,RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from docx.enum.section import WD_SECTION_START,WD_ORIENT
from docx.oxml import OxmlElement
from docx.oxml.ns import qn
ROOT=Path(__file__).resolve().parents[1]
D=Document()
LABEL={'text_only':'Только текст','numeric_only':'Только числа','image_only':'Только график','early_fusion':'Early fusion','late_mean':'Late mean','late_weighted':'Late weighted','intermediate_mlp':'MLP fusion','attention_fusion':'Attention fusion'}
def read(p):
    with (ROOT/p).open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
def js(p):return json.loads((ROOT/p).read_text(encoding='utf-8-sig'))
def fmt(x,n=3):return f'{float(x):.{n}f}'.replace('.',',')
def p(text='',bold=False):
    x=D.add_paragraph();r=x.add_run(text);r.bold=bold;return x
def h(text):D.add_heading(text,level=1)
def new(text):
    x=D.add_heading(text,level=1);x.paragraph_format.page_break_before=True
def picture(name,width=16):D.add_picture(str(ROOT/'figures'/name),width=Cm(width))
def caption(text):
    x=p(text);x.paragraph_format.space_after=Pt(6)
    for r in x.runs:r.font.size=Pt(9)
def table(headers,rows,widths=None,size=9.5):
    t=D.add_table(rows=1,cols=len(headers));t.autofit=False
    if widths:
        for col,w in zip(t.columns,widths):col.width=Cm(w)
    for cell,value in zip(t.rows[0].cells,headers):cell.text=str(value)
    repeat=OxmlElement('w:tblHeader');t.rows[0]._tr.get_or_add_trPr().append(repeat)
    for row in rows:
        for cell,value in zip(t.add_row().cells,row):cell.text=str(value)
    for i,row in enumerate(t.rows):
        trpr=row._tr.get_or_add_trPr();no=OxmlElement('w:cantSplit');trpr.append(no)
        for j,cell in enumerate(row.cells):
            if widths:cell.width=Cm(widths[j])
            pr=cell._tc.get_or_add_tcPr();borders=OxmlElement('w:tcBorders')
            for edge in ['top','left','bottom','right']:
                e=OxmlElement('w:'+edge);e.set(qn('w:val'),'single');e.set(qn('w:sz'),'4');e.set(qn('w:color'),'D9D9D9');borders.append(e)
            pr.append(borders);marg=OxmlElement('w:tcMar')
            for edge in ['top','left','bottom','right']:
                e=OxmlElement('w:'+edge);e.set(qn('w:w'),'70');e.set(qn('w:type'),'dxa');marg.append(e)
            pr.append(marg)
            if i==0:
                sh=OxmlElement('w:shd');sh.set(qn('w:fill'),'E8EDF2');pr.append(sh)
            for para in cell.paragraphs:
                para.paragraph_format.space_after=Pt(2);para.paragraph_format.space_before=Pt(2);para.paragraph_format.line_spacing=1
                for r in para.runs:r.font.size=Pt(size);r.bold=i==0
    p();return t
def link(url,text=None):
    para=D.add_paragraph();hyp=OxmlElement('w:hyperlink');rid=para.part.relate_to(url,'http://schemas.openxmlformats.org/officeDocument/2006/relationships/hyperlink',is_external=True);hyp.set(qn('r:id'),rid)
    r=OxmlElement('w:r');pr=OxmlElement('w:rPr');sz=OxmlElement('w:sz');sz.set(qn('w:val'),'19');pr.append(sz);r.append(pr);t=OxmlElement('w:t');t.text=text or url;r.append(t);hyp.append(r);para._p.append(hyp)
def section(landscape=False):
    s=D.add_section(WD_SECTION_START.NEW_PAGE);s.orientation=WD_ORIENT.LANDSCAPE if landscape else WD_ORIENT.PORTRAIT
    s.page_width=Cm(29.7 if landscape else 21);s.page_height=Cm(21 if landscape else 29.7)
    s.top_margin=s.bottom_margin=Cm(1.6 if landscape else 1.8);s.left_margin=s.right_margin=Cm(1.7 if landscape else 2)
    return s

def main():
    q=js('data/quality_summary.json');run=js('results/run_summary.json');lit=js('research/literature.json')
    m={r['model']:r for r in read('results/metrics.csv') if r['split']=='test'}
    cis={(r['model'],r['metric']):r for r in read('results/confidence_intervals.csv') if r['block_sessions']=='5'}
    resources={r['model']:r for r in read('results/resources.csv')}
    normal=D.styles['Normal'];normal.font.name='Times New Roman';normal.font.size=Pt(11)
    normal.paragraph_format.line_spacing=1.12;normal.paragraph_format.space_after=Pt(6)
    for style,size in [('Title',19),('Heading 1',14),('Heading 2',12)]:
        D.styles[style].font.name='Times New Roman';D.styles[style].font.size=Pt(size);D.styles[style].font.color.rgb=RGBColor(0,0,0)
    for style in D.styles:
        for border in list(style.element.findall('.//'+qn('w:pBdr'))):border.getparent().remove(border)
    s=D.sections[0];s.page_width=Cm(21);s.page_height=Cm(29.7);s.top_margin=s.bottom_margin=Cm(1.8);s.left_margin=s.right_margin=Cm(2)
    foot=s.footer.paragraphs[0];foot.alignment=WD_ALIGN_PARAGRAPH.CENTER
    field=OxmlElement('w:fldSimple');field.set(qn('w:instr'),'PAGE');foot._p.append(field)
